package main

import (
	"fmt"
	"html"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail generates an HTML-formatted email string ready to be sent via net/smtp.
// It constructs the necessary MIME headers and HTML body.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	if fromAddr == "" || toAddr == "" {
		return "", fmt.Errorf("fromAddr and toAddr cannot be empty")
	}

	// Escape HTML characters to prevent XSS and formatting issues
	safeUserName := html.EscapeString(userName)
	safeSubject := html.EscapeString(subject)
	safeContent := html.EscapeString(feedbackContent)

	// Replace newlines with HTML <br> tags for proper rendering in email clients
	safeContent = strings.ReplaceAll(safeContent, "\n", "<br>")

	// Create the HTML structure
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Feedback: %s</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <h2 style="color: #0056b3;">New User Feedback</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <hr style="border: 0; border-top: 1px solid #eee;">
    <h3>Feedback Content:</h3>
    <p>%s</p>
</body>
</html>`, safeSubject, safeUserName, safeSubject, safeContent)

	// Construct the raw email message (Headers + Body) as required by net/smtp.SendMail
	var msg strings.Builder
	msg.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", subject))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"UTF-8\"\r\n")
	msg.WriteString("\r\n") // Empty line between headers and body is mandatory per RFC 5322
	msg.WriteString(htmlBody)

	return msg.String(), nil
}

// SendFeedbackEmail demonstrates how to use the net/smtp package to send the constructed email.
func SendFeedbackEmail(smtpHost, smtpPort, username, password, from, to, emailBody string) error {
	auth := smtp.PlainAuth("", username, password, smtpHost)
	addr := fmt.Sprintf("%s:%s", smtpHost, smtpPort)
	return smtp.SendMail(addr, auth, from, []string{to}, []byte(emailBody))
}

func main() {
	from := "noreply@example.com"
	to := "support@example.com"
	userName := "johndoe_99"
	subject := "Login Issue"
	content := "Hello,\n\nI am unable to log in to my account. It keeps showing a 500 Internal Server Error.\n\nPlease help!\nThanks,\nJohn"

	// 1. Build the email content
	emailBody, err := BuildFeedbackEmail(from, to, userName, subject, content)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println("--- Generated Email Content ---")
	fmt.Println(emailBody)
