// Note: The standard library's net/smtp package is used for *sending* emails rather than constructing 
// the MIME/HTML content. Therefore, we construct the raw email message manually and provide a 
// helper function using net/smtp to demonstrate how to dispatch it to the SMTP server.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("all fields are required")
	}

	// Prevent SMTP header injection attacks
	headerSubject := strings.ReplaceAll(subject, "\r", " ")
	headerSubject = strings.ReplaceAll(headerSubject, "\n", " ")

	// Escape HTML special characters to prevent XSS and ensure proper rendering
	escapedUser := html.EscapeString(userName)
	escapedSubject := html.EscapeString(subject)
	escapedContent := html.EscapeString(feedbackContent)

	// Construct the HTML part
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <h2 style="color: #0056b3;">New User Feedback Received</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <p><strong>Feedback Content:</strong></p>
    <div style="background-color: #f4f4f9; padding: 15px; border-left: 5px solid #0056b3; margin-top: 10px; white-space: pre-wrap;">%s</div>
    <hr>
    <p style="font-size: 12px; color: #888;">This is an automated message generated by the user feedback system.</p>
</body>
</html>`, escapedUser, escapedSubject, escapedContent)

	// Construct the RFC 5322 email headers
	var msg strings.Builder
	msg.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", headerSubject))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"utf-8\"\r\n")
	msg.WriteString("\r\n") // Blank line separating headers from body
	msg.WriteString(htmlBody)

	return msg.String(), nil
}

// SendFeedbackEmail uses the net/smtp package to send the constructed email to the customer support team.
func SendFeedbackEmail(smtpServer string, auth smtp.Auth, fromAddr string, toAddr string, emailBody string) error {
	return smtp.SendMail(smtpServer, auth, fromAddr, []string{toAddr}, []byte(emailBody))
}

func main() {
	from := "noreply@myapp.com"
	to := "support@myapp.com"
	user := "John Doe"
	subj := "Feature Request: Dark Mode"
	content := "I would love to see a dark mode option in the settings.\nIt really helps when working at night."

	emailBody, err := BuildFeedbackEmail(from, to, user, subj, content)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println("----- Generated Email Content -----")
	fmt.Println(emailBody)
	fmt.Println("-----------------------------------")

	// Demonstrate how to use net/smtp to send the email
	// Note: We are not actually executing the send command here to avoid network errors in a demo environment.
	smtpServer := "smtp.myapp.com:587"
	auth := smtp.PlainAuth("", "noreply@myapp.com", "password", "smtp.myapp.com")

	fmt.Printf("\nTo send this email to the support team, you would execute:\nSendFeedbackEmail(%q, auth, %q, %q, emailBody)\n", smtpServer, from, to)
	_ = auth // Suppress unused variable error for demonstration purposes
}

