import (
	"fmt"
	"html"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail generates an HTML-formatted email body for user feedback.
// The returned emailBody is a raw RFC 822 message string, which is the format
// expected by the net/smtp package for sending emails.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Escape HTML entities to prevent injection and ensure proper rendering
	escapedUser := html.EscapeString(userName)
	escapedSubject := html.EscapeString(subject)
	escapedContent := html.EscapeString(feedbackContent)

	// Preserve line breaks in the feedback content for HTML display
	escapedContent = strings.ReplaceAll(escapedContent, "\r\n", "<br>")
	escapedContent = strings.ReplaceAll(escapedContent, "\n", "<br>")

	// Construct email headers
	headers := []string{
		fmt.Sprintf("From: %s", fromAddr),
		fmt.Sprintf("To: %s", toAddr),
		fmt.Sprintf("Subject: %s", subject),
		"MIME-Version: 1.0",
		"Content-Type: text/html; charset=\"UTF-8\"",
	}

	// Construct HTML body
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
</head>
<body>
    <h2>New User Feedback Received</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <hr>
    <p><strong>Feedback Content:</strong></p>
    <div>%s</div>
</body>
</html>`, escapedUser, escapedSubject, escapedContent)

	// Combine headers and body with RFC 822 standard CRLF separators
	emailBody = strings.Join(headers, "\r\n") + "\r\n\r\n" + htmlBody
	return emailBody, nil
}

