            <div class="info-row"><span class="label">Subject:</span> {{.Subject}}</div>
            <div class="info-row">
                <span class="label">Feedback Content:</span>
                <div class="feedback-box">{{.Content}}</div>
            </div>
        </div>
    </div>
</body>
</html>`

	tmpl, err := template.New("feedback").Parse(htmlTemplate)
	if err != nil {
		return "", fmt.Errorf("failed to parse HTML template: %w", err)
	}

	var htmlBody bytes.Buffer
	data := struct {
		UserName string
		Subject  string
