// BuildFeedbackEmail generates an HTML-formatted raw email string.
// The returned string is formatted according to RFC 5322 (headers + body)
// and is constructed specifically to be passed as the message payload
// to the net/smtp package's SendMail function.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// HTML template for the email body. 
	// Using html/template ensures user inputs are safely escaped to prevent XSS in email clients.
	const htmlTpl = `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
        .container { max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #ddd; border-radius: 5px; }
        .header { background-color: #f4f4f4; padding: 10px; border-bottom: 1px solid #ddd; }
        .content { padding: 15px 0; }
        .feedback-box { background-color: #f9f9f9; padding: 15px; border-left: 4px solid #007bff; white-space: pre-wrap; }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h2>New User Feedback Received</h2>
        </div>
        <div class="content">
            <p><strong>Username:</strong> {{.UserName}}</p>
            <p><strong>Subject:</strong> {{.Subject}}</p>
            <hr>
            <p><strong>Feedback Content:</strong></p>
            <div class="feedback-box">{{.FeedbackContent}}</div>
        </div>
    </div>
</body>
</html>`

	t, err := template.New("feedback").Parse(htmlTpl)
	if err != nil {
		return "", fmt.Errorf("failed to parse HTML template: %w", err)
	}

	var bodyBuf bytes.Buffer
	err = t.Execute(&bodyBuf, map[string]string{
		"UserName":        userName,
		"Subject":         subject,
		"FeedbackContent": feedbackContent,
	})
	if err != nil {
		return "", fmt.Errorf("failed to execute HTML template: %w", err)
	}

	// Encode subject using MIME Q-encoding to safely support non-ASCII characters
	encodedSubject := mime.QEncoding.Encode("utf-8", subject)

	// Construct the raw RFC 5322 email message (Headers + Empty Line + Body)
	var msg bytes.Buffer
	msg.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", encodedSubject))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"utf-8\"\r\n")
	msg.WriteString("\r\n") // Empty line separating headers from body
	msg.Write(bodyBuf.Bytes())

	return msg.String(), nil
}

