func SendFeedbackEmail(smtpAddr string, auth smtp.Auth, fromAddr string, toAddr string, emailBody string) error {
	// net/smtp requires the message to be a raw byte slice containing both headers and body
	return smtp.SendMail(smtpAddr, auth, fromAddr, []string{toAddr}, []byte(emailBody))
}

