// BuildFeedbackEmail generates an HTML-formatted email body with proper MIME headers
// compatible with the net/smtp package.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Sanitize headers to prevent SMTP header injection attacks
	sanitizeHeader := func(s string) string {
		s = strings.ReplaceAll(s, "\r", "")
		s = strings.ReplaceAll(s, "\n", "")
		return s
	}

	fromAddr = sanitizeHeader(fromAddr)
	toAddr = sanitizeHeader(toAddr)
	subject = sanitizeHeader(subject)

	// Construct RFC 822 compliant headers
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"UTF-8\"\r\n\r\n",
		fromAddr, toAddr, subject)

	// Construct HTML body, escaping user inputs to prevent XSS
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333;">
    <h2 style="color: #0056b3;">User Feedback Received</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <p><strong>Feedback Content:</strong></p>
    <div style="background-color: #f9f9f9; padding: 15px; border: 1px solid #ddd; border-radius: 5px; white-space: pre-wrap;">%s</div>
    <br>
    <p style="font-size: 12px; color: #888;">This is an automated message generated by the feedback system.</p>
</body>
</html>`, html.EscapeString(userName), html.EscapeString(subject), html.EscapeString(feedbackContent))

	// Ensure all line endings in the body are \r\n for strict SMTP compliance
	htmlBody = strings.ReplaceAll(htmlBody, "\n", "\r\n")

	return headers + htmlBody, nil
}

// SendFeedbackEmail demonstrates how to use the net/smtp package to send the constructed email.
func SendFeedbackEmail(smtpAddr string, auth smtp.Auth, fromAddr string, toAddr string, userName string, subject string, feedbackContent string) error {
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		return fmt.Errorf("failed to build email: %w", err)
	}

	// net/smtp.SendMail requires the message as a byte slice
	msg := []byte(emailBody)

	// Send the email
	err = smtp.SendMail(smtpAddr, auth, fromAddr, []string{toAddr}, msg)
	if err != nil {
		return fmt.Errorf("failed to send email: %w", err)
	}

	return nil
}

