// BuildFeedbackEmail constructs an RFC 822 formatted HTML email string 
// ready to be sent via the net/smtp package.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	var msg bytes.Buffer

	// sanitizeHeader prevents CRLF header injection attacks
	sanitizeHeader := func(s string) string {
		s = strings.ReplaceAll(s, "\r", "")
		s = strings.ReplaceAll(s, "\n", "")
		return s
	}

	// Construct Email Headers
	msg.WriteString(fmt.Sprintf("From: %s\r\n", sanitizeHeader(fromAddr)))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", sanitizeHeader(toAddr)))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", sanitizeHeader(subject)))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"utf-8\"\r\n")
	msg.WriteString("\r\n") // Blank line separating headers from body

	// Escape HTML entities to prevent formatting issues and XSS
	escapedUser := html.EscapeString(userName)
	escapedSubject := html.EscapeString(subject)
	escapedContent := html.EscapeString(feedbackContent)

	// Construct HTML Body
	htmlTemplate := `<!DOCTYPE html>
