    <div class="container">
        <h2>New User Feedback Received</h2>
        <div class="meta-info">
            <p><span class="label">Username:</span> %s</p>
            <p><span class="label">Subject:</span> %s</p>
        </div>
        <hr>
        <p class="label">Feedback Details:</p>
        <div class="feedback-box">%s</div>
