}

// SendWithSMTP demonstrates how to use the net/smtp package to send the constructed email.
func SendWithSMTP(smtpAddr, username, password, from string, to []string, emailBody string) error {
	host := strings.Split(smtpAddr, ":")[0]
	auth := smtp.PlainAuth("", username, password, host)
	return smtp.SendMail(smtpAddr, auth, from, to, []byte(emailBody))
}

