// BuildFeedbackEmail generates an HTML-formatted email body with proper RFC 5322 headers.
// The resulting string is formatted to be directly passed to net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Construct headers according to RFC 5322 (using CRLF line endings)
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"utf-8\"\r\n\r\n",
		fromAddr, toAddr, subject)

	// HTML template for the email body. 
	// Using html/template ensures user-submitted content is safely escaped to prevent XSS in email clients.
	const bodyTemplate = `<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>User Feedback</title>
</head>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto;">
    <h2 style="color: #2c3e50; border-bottom: 2px solid #3498db; padding-bottom: 10px;">User Feedback</h2>
    <p><strong>Username:</strong> {{.UserName}}</p>
    <p><strong>Subject:</strong> {{.Subject}}</p>
    <hr style="border: 0; border-top: 1px solid #eee;">
    <h3 style="color: #555;">Feedback Content:</h3>
    <div style="background-color: #f9f9f9; padding: 15px; border-radius: 5px; border-left: 4px solid #3498db; white-space: pre-wrap;">{{.FeedbackContent}}</div>
</body>
</html>`

	tmpl, err := template.New("emailBody").Parse(bodyTemplate)
	if err != nil {
		return "", fmt.Errorf("failed to parse email template: %w", err)
	}

	data := map[string]string{
		"UserName":        userName,
		"Subject":         subject,
		"FeedbackContent": feedbackContent,
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return "", fmt.Errorf("failed to execute email template: %w", err)
	}

	return headers + buf.String(), nil
}

// SendFeedbackEmail demonstrates using the net/smtp package to send the constructed email.
func SendFeedbackEmail(smtpAddr string, auth smtp.Auth, fromAddr string, toAddr string, userName string, subject string, feedbackContent string) error {
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		return err
	}
	// net/smtp.SendMail expects the raw RFC 5322 message as a byte slice
	return smtp.SendMail(smtpAddr, auth, fromAddr, []string{toAddr}, []byte(emailBody))
}

