package main

import (
	"bytes"
	"fmt"
	"html/template"
	"net/smtp"
)

// BuildFeedbackEmail generates an HTML-formatted email message string
// that is ready to be sent using the net/smtp package.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	htmlTemplate := `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body>
    <h2>User Feedback</h2>
    <p><strong>Username:</strong> {{.UserName}}</p>
    <p><strong>Subject:</strong> {{.Subject}}</p>
    <p><strong>Feedback Content:</strong></p>
    <div style="background-color: #f9f9f9; padding: 15px; border: 1px solid #ddd; border-radius: 5px; white-space: pre-wrap;">{{.FeedbackContent}}</div>
</body>
</html>`

	tmpl, err := template.New("feedback").Parse(htmlTemplate)
	if err != nil {
		return "", fmt.Errorf("failed to parse template: %w", err)
	}

	var bodyBuf bytes.Buffer
	data := struct {
		UserName        string
		Subject         string
		FeedbackContent string
	}{
		UserName:        userName,
		Subject:         subject,
		FeedbackContent: feedbackContent,
	}

	if err := tmpl.Execute(&bodyBuf, data); err != nil {
		return "", fmt.Errorf("failed to execute template: %w", err)
	}

	// Construct the raw RFC 822 email message (headers + HTML body)
	// This string format is exactly what net/smtp.SendMail expects
	msg := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=\"utf-8\"\r\n\r\n%s",
		fromAddr, toAddr, subject, bodyBuf.String())

	return msg, nil
}

// SendFeedbackEmail is a helper function demonstrating how to use the net/smtp 
// package to send the email content generated by BuildFeedbackEmail.
func SendFeedbackEmail(smtpAddr, smtpUser, smtpPass, fromAddr, toAddr, userName, subject, feedbackContent string) error {
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		return err
	}

	// Set up authentication information.
	auth := smtp.PlainAuth("", smtpUser, smtpPass, "smtp.example.com")

	// Connect to the server, authenticate, set the sender and recipient,
	// and send the email all in one step.
	err = smtp.SendMail(smtpAddr, auth, fromAddr, []string{toAddr}, []byte(emailBody))
	if err != nil {
		return fmt.Errorf("failed to send email: %w", err)
	}
	return nil
}

func main() {
	from := "noreply@example.com"
	to := "support@example.com"
	user := "john_doe"
	subj := "Application Crash on Startup"
	content := "Hi Support Team,\n\nWhenever I try to open the dashboard, the application crashes immediately.\n\nSteps to reproduce:\n1. Login\n2. Click on Dashboard\n\nThanks,\nJohn"

	emailMsg, err := BuildFeedbackEmail(from, to, user, subj, content)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	fmt.Println("Generated Raw Email Message (Ready for net/smtp):")
	fmt.Println("---------------------------------------------------")
	fmt.Println(emailMsg)
}

